//! Session handling.
//!
//! Sessions expire after the configured idle time (in seconds).

pub struct Session {
    pub user: String,
    pub idle_secs: u64,
}

pub fn expired(s: &Session, limit: u64) -> bool {
    s.idle_secs > limit
}

