pub fn charge(cents: u64) -> Result<u64, String> {
    let confirmed = gateway(cents)?;
    let receipt = store(confirmed)?;
    Ok(receipt)
}

fn gateway(c: u64) -> Result<u64, String> { Ok(c) }
fn store(c: u64) -> Result<u64, String> { Ok(c) }

